import{_ as a,o as s,c as o,a6 as i}from"./chunks/framework.CKIbuWFA.js";const m=JSON.parse('{"title":"Contribua com alterações focadas","description":"","frontmatter":{"title":"Contribua com alterações focadas","docId":"developer.contributing","translationKey":"developer.contributing","locale":"pt","audience":"developer","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"2e0522178ebee69ea5eb20fec3c0ec586f13950c51d658cb3a21843536b2f9f9","translationRevision":"55a568d4e9d9f662d37d2514d1ad8438c4cac4a79b3ea481043e9232409772c1","order":230},"headers":[],"relativePath":"pt/developer/contributing.md","filePath":"pt/developer/contributing.md","lastUpdated":1794611623000}'),t={name:"pt/developer/contributing.md"};function r(n,e,d,c,l,p){return s(),o("div",null,[...e[0]||(e[0]=[i(`<h1 id="contributing-focused-changes" tabindex="-1">Contribua com alterações focadas <a class="header-anchor" href="#contributing-focused-changes" aria-label="Permalink to &quot;Contribua com alterações focadas {#contributing-focused-changes}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objetivo e pré-requisitos <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Objetivo e pré-requisitos {#goal-and-prerequisites}&quot;">​</a></h2><p>Prepare uma alteração que outro contribuidor possa revisar e verificar. Leia o <a href="https://github.com/nglmercer/TikTools-app/blob/remake/CONTRIBUTING.md" target="_blank" rel="noreferrer">CONTRIBUTING.md</a> do repositório, os arquivos <code>AGENTS.md</code> aplicáveis e a <a href="./setup.html">configuração</a> antes de editar. Use Bun 1.4.4, Rust 1.95 ou mais recente quando necessário, lockfiles versionados e uma branch baseada no destino pretendido.</p><h2 id="define-and-implement-the-change" tabindex="-1">Defina e implemente a alteração <a class="header-anchor" href="#define-and-implement-the-change" aria-label="Permalink to &quot;Defina e implemente a alteração {#define-and-implement-the-change}&quot;">​</a></h2><ol><li>Inspecione <code>git status</code> e preserve trabalho de outras pessoas. Mantenha recursos gerados, credenciais e bancos de dados locais fora do patch.</li><li>Siga o responsável atual pelo código: núcleo Rust para comportamento de serviços, módulos da API de controle para contratos, cliente tipado para cobertura do SDK e o <a href="./frontend.html">mapa de camadas do frontend</a> para apresentação.</li><li>Para uma alteração de contrato, atualize sua definição canônica e regenere a saída derivada em conjunto. Não mantenha manualmente outra tabela completa de esquemas RPC ou eventos.</li><li>Mantenha implementações específicas de plugins em seus pacotes externos; código genérico do host deve descobrir manifestos em vez de importar um plugin pelo nome.</li><li>Explique o acionador concreto e o comportamento resultante, incluindo caminhos incompletos ou experimentais.</li></ol><h2 id="validate-proportionately" tabindex="-1">Valide proporcionalmente <a class="header-anchor" href="#validate-proportionately" aria-label="Permalink to &quot;Valide proporcionalmente {#validate-proportionately}&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> frontend-lint</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> frontend-test</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> frontend-build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> contracts</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --check</span></span></code></pre></div><p>Alterações de implementação nativa também precisam das verificações aplicáveis de formatação/lint/testes Rust e controles obrigatórios da CI. Uma alteração apenas de documentação deve usar verificações de documentação e revisar seus comandos/links de código, em vez de afirmar aceitação da execução nativa. O executor de tarefas do projeto define os pontos de entrada aceitos; use o repasse ao Cargo para flags específicas de alvos nativos.</p><h2 id="expected-result-and-status" tabindex="-1">Resultado esperado e status <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;Resultado esperado e status {#expected-result-and-status}&quot;">​</a></h2><p>A revisão contém alterações focadas de código, evidências significativas de validação e limites honestos. A política do repositório direciona pull requests para <code>remake</code>; tags de lançamento são controladas pelos mantenedores. As instruções de contribuição estão disponíveis, mas proteção de branches e configuração de verificações remotas são responsabilidades de administradores, não garantias de uma página Markdown.</p><h2 id="recover" tabindex="-1">Recupere <a class="header-anchor" href="#recover" aria-label="Permalink to &quot;Recupere {#recover}&quot;">​</a></h2><p>Se a validação falhar por dependência ou biblioteca de plataforma ausente, informe e corrija o ambiente em vez de enfraquecer uma verificação. Se arquivos gerados divergirem, regenere a partir de sua fonte responsável e inspecione a diferença. Nunca publique cookies de sessão, chaves, credenciais ou capturas de eventos não sanitizadas. Se código e um projeto legado divergirem, descreva a discrepância e use a implementação atual nas orientações públicas. Não sobrescreva arquivos pendentes de outro responsável para fazer uma limpeza ampla parecer consistente.</p><h2 id="operational-details" tabindex="-1">Detalhes de operação <a class="header-anchor" href="#operational-details" aria-label="Permalink to &quot;Detalhes de operação {#operational-details}&quot;">​</a></h2><p>Selos têm significados separados: <code>sourceRevision</code> resume o corpo inglês atual e <code>translationRevision</code> o corpo localizado (sem frontmatter/espaço externo). Após revisar fonte e traduções use <code>bun docs/scripts/record-review.ts developer/example.md</code>. Edições posteriores invalidam o selo correspondente. Detecta alterações, não identidade humana nem equivalência semântica: compare comandos, IDs RPC/ambiente, chaves payload, limites, ativação/recuperação e negações. Traduza prosa completa mantendo instruções técnicas.</p><p>Para migração dividida registre tema/título original e destino concreto no mapa, usando fragmento para seção. O checker valida arquivos/fragmentos e bytes históricos, mas revisão editorial verifica cobertura temática. Não edite originais/provenance históricos para aprovar.</p>`,15)])])}const h=a(t,[["render",r]]);export{m as __pageData,h as default};
